/* ROM tile archive reader and per-entry tile enumeration for the S2 Body E
 * per-object VDP1 renderer.
 *
 * The archive (cd/SPR4/TILES.BIN, generated by tools/gen_avsp_gfx_tiles.py)
 * carries every 16x16 tile the corpus-decoded CPS2 object entries reference,
 * already converted to VDP1 4bpp bank-mode texture bytes (pen 15 -> pixel 0
 * transparent, visible pen p -> pixel p+1 per Jo's CRAM base+1 convention),
 * plus the Saturn CRAM colours for each referenced CPS2 palette bank.
 *
 * avsp_entry_tiles is a transcription of MAME 0.289 cps2_render_sprites'
 * block expansion: the non-flipped read wraps within the 16-tile row while
 * any flipped read runs linearly, and flipped blocks draw mirrored tile
 * order with per-tile flip. Pure C90, no Saturn or Jo dependencies, so the
 * host suite can falsify it against the same captures as the emitter.
 */
#ifndef AVSP_TILES_H
#define AVSP_TILES_H

#define AVSP_TILE_BYTES 128
#define AVSP_TILE_MAGIC 0x4156544CUL /* 'AVTL' */

typedef struct
{
    const unsigned char *data;
    unsigned long size;
    unsigned long tile_count;
    unsigned long palette_slots;
    const unsigned char *bank_map; /* [32] CPS2 colour -> slot, 0xFF unused */
    const unsigned char *cram;     /* palette_slots*16 big-endian u16 */
    const unsigned char *codes;    /* tile_count big-endian u32, ascending */
    const unsigned char *tiles;    /* tile_count * AVSP_TILE_BYTES */
} AvspTileArchive;

/* Parse and bounds-check the archive header. Returns 1 on success. */
int avsp_tiles_open(AvspTileArchive *archive, const unsigned char *data,
                    unsigned long size);

/* Rank of a tile code in the archive, or -1 when absent. */
long avsp_tiles_find(const AvspTileArchive *archive, unsigned long code);

/* Texture bytes of the tile at a rank returned by avsp_tiles_find. */
const unsigned char *avsp_tiles_texture(const AvspTileArchive *archive,
                                        long rank);

/* Tile code at a rank (inverse of avsp_tiles_find). */
unsigned long avsp_tiles_code(const AvspTileArchive *archive, long rank);

/* Palette slot for a CPS2 colour bank 0..31, or -1 when not in the
 * archive. */
int avsp_tiles_bank_slot(const AvspTileArchive *archive, int cps_bank);

/* Saturn CRAM colour (RGB555 | 0x8000) for a slot's entry 0..15. */
unsigned int avsp_tiles_cram_color(const AvspTileArchive *archive, int slot,
                                   int index);

/* One 16x16 tile of an expanded object entry. dx/dy are pixel offsets from
 * the entry's top-left corner; flips select CMDCTRL-style mirrored reads. */
typedef struct
{
    unsigned long code;
    short dx;
    short dy;
    unsigned char flip_x;
    unsigned char flip_y;
} AvspEntryTile;

/* Expand one CPS2 object entry (the emitter's y/code/attr words) into its
 * tile draw list. Returns the tile count, or -1 when max_out is too small.
 * Entry X placement is the caller's: the emitter already bakes facing into
 * the entry's X word, so tiles place left-to-right from the entry corner in
 * every case. */
int avsp_entry_tiles(unsigned short y, unsigned short code,
                     unsigned short attr, AvspEntryTile *out, int max_out);

/* Compose one expanded CPS2 object entry into a single VDP1 4bpp texture.
 * The result preserves the source tile order and both per-tile flip axes.
 * Returns the byte count written, -1 for a missing source tile, or 0 when
 * the destination is too small/invalid. */
long avsp_compose_entry_texture(const AvspTileArchive *archive,
                                unsigned short y, unsigned short code,
                                unsigned short attr, unsigned char *out,
                                unsigned long out_bytes);

#endif
